record.field:
# Mapping approval to pdf sign # Available variables: # - approval_instance # - transaction_object # - approval_task_line # - user_execution # To return an response, assign: response = {...}
report = ref('amr_esign_pdf_demo.action_report_approval_form') pdf_content, content_type = report.render_qweb_pdf(transaction_object.ids)
requester = approval_instance.requester_id or user signature_ids = [{ 'seq':0, 'name':'signature_requester', 'user_id':requester.id, 'user_email':requester.email, 'placeholder':"[[signature_requester_placeholder]]", 'auto_sign_after_request':True }] approval_task_line = approval_instance.get_all_approval_task_line() if approval_task_line: seq=1 for apr in approval_task_line: signature_ids.append({ 'seq':seq, 'name':'signature_approvar_%s'%apr.id, 'placeholder': "[[signature_approvar_%s_placeholder]]"%apr.id, 'source_model': apr._name, 'source_res_id': apr.id, }) seq+=1
response = { 'name':transaction_object.name, 'template_id':1, 'source_model': approval_instance.transaction_model_name, 'source_res_id': approval_instance.transaction_id, 'pdf_file': b64encode(pdf_content), 'pdf_filename':'approval_%s.pdf'%transaction_object.name, 'signature_ids': signature_ids, }
